// Bestimmt die Zielwoche (ISO-Kalenderwoche + Montag der KOMMENDEN Woche) und
// faechert ueber die Google-Kalender auf (ein Item je Kalender fuer den Termin-Abruf).
// Payload vom Frontend (nobraine.html): { weekKey, startDatum, tage, slots, freeblocks, typ, ... }
// Fehlt der Payload (oder ist er unvollstaendig), wird die kommende Woche ab heute berechnet.
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});

function pad2(n) { return String(n).padStart(2, '0'); }
function isoDatum(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }

// ISO-8601-Kalenderwoche (Woche des Donnerstags)
function isoWoche(d) {
  const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const wochentag = t.getUTCDay() || 7; // Mo=1 ... So=7
  t.setUTCDate(t.getUTCDate() + 4 - wochentag);
  const jahresanfang = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  const kw = Math.ceil(((t.getTime() - jahresanfang.getTime()) / 86400000 + 1) / 7);
  return { jahr: t.getUTCFullYear(), kw: kw };
}

// Montag der KOMMENDEN Woche (immer der naechste Montag, nie der heutige Tag)
function naechsterMontag(ab) {
  const d = new Date(ab.getFullYear(), ab.getMonth(), ab.getDate());
  const delta = ((8 - d.getDay()) % 7) || 7;
  d.setDate(d.getDate() + delta);
  return d;
}

let montag;
if (typeof body.startDatum === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(body.startDatum)) {
  const teile = body.startDatum.split('-');
  montag = new Date(Number(teile[0]), Number(teile[1]) - 1, Number(teile[2]));
} else {
  montag = naechsterMontag(new Date());
}
const sonntag = new Date(montag.getFullYear(), montag.getMonth(), montag.getDate() + 6);
const w = isoWoche(montag);
const weekKey = (typeof body.weekKey === 'string' && /^\d{4}-W\d{2}$/.test(body.weekKey))
  ? body.weekKey
  : (w.jahr + '-W' + pad2(w.kw));

// Google-Kalender, deren Termine die Essensplanung beeinflussen.
// Platzhalter nach dem Import durch echte Kalender-IDs ersetzen.
const calendars = [
  'REPLACE_PRIMARY_CALENDAR_ID',
  'REPLACE_PARTNER_CALENDAR_ID',
  'REPLACE_FAMILY_CALENDAR_ID'
];

// Nutzer-Prefs (Ziel / Kalorien-Tendenz / Trainingstage) normalisieren - steuern die KI.
const prefsRoh = (body.prefs && typeof body.prefs === 'object') ? body.prefs : {};
const prefs = {
  goal: (prefsRoh.goal === 'lose' || prefsRoh.goal === 'gain') ? prefsRoh.goal : 'maintain',
  calorieTrend: (prefsRoh.calorieTrend === 'less' || prefsRoh.calorieTrend === 'more') ? prefsRoh.calorieTrend : 'normal',
  trainingDays: Array.isArray(prefsRoh.trainingDays) ? prefsRoh.trainingDays.filter(function (d) { return typeof d === 'string'; }) : []
};

return calendars.map(function (calendarId, index) {
  return { json: {
    calendarId: calendarId,
    calendarIndex: index,
    weekKey: weekKey,
    jahr: w.jahr,
    kw: w.kw,
    startDatum: isoDatum(montag),
    endDatum: isoDatum(sonntag),
    timeMin: isoDatum(montag) + 'T00:00:00Z',
    timeMax: isoDatum(new Date(sonntag.getFullYear(), sonntag.getMonth(), sonntag.getDate() + 1)) + 'T00:00:00Z',
    tage: Number(body.tage) || 7,
    slots: Array.isArray(body.slots) ? body.slots : ['mittag', 'abend'],
    freeblocks: Array.isArray(body.freeblocks) ? body.freeblocks : [],
    typ: body.typ === 'slot' ? 'slot' : 'woche',
    tag: (typeof body.tag === 'string') ? body.tag : null,
    slot: (typeof body.slot === 'string') ? body.slot : null,
    prefs: prefs
  } };
});

// Aggregiert die Kalender-Antworten ALLER Kalender zu Busy-Flags je Wochentag.
// Fenster: Mittag 11:30-13:30, Abend 18:00-20:30. Ueberlappt ein Termin das
// Fenster (oder ist er ganztaegig), gilt der Slot als belegt.
// Belegter Mittag => microwaveOnly: das vorgekochte Essen muss nur aufwaermbar sein.
const basis = $('Woche berechnen').first().json;
const TAGE = ['montag', 'dienstag', 'mittwoch', 'donnerstag', 'freitag', 'samstag', 'sonntag'];

const startTeile = String(basis.startDatum).split('-');
const wochenstart = new Date(Number(startTeile[0]), Number(startTeile[1]) - 1, Number(startTeile[2]));

const proTag = {};
for (const t of TAGE) proTag[t] = { termine: [], mittagBusy: false, abendBusy: false };

function ueberlappt(beginn, ende, tagDatum, vonH, vonM, bisH, bisM) {
  const von = new Date(tagDatum.getFullYear(), tagDatum.getMonth(), tagDatum.getDate(), vonH, vonM, 0);
  const bis = new Date(tagDatum.getFullYear(), tagDatum.getMonth(), tagDatum.getDate(), bisH, bisM, 0);
  return beginn < bis && ende > von;
}

for (const item of $input.all()) {
  const antwort = (item && item.json) ? item.json : {};
  // Fehler-Antworten (z. B. Platzhalter-Kalender, 404) liefern kein items[] und werden uebersprungen
  const events = Array.isArray(antwort.items) ? antwort.items : [];
  for (const ev of events) {
    if (!ev || ev.status === 'cancelled') continue;
    const ganztags = !!(ev.start && ev.start.date && !ev.start.dateTime);
    const beginn = ganztags
      ? new Date(ev.start.date + 'T00:00:00')
      : new Date(String((ev.start && ev.start.dateTime) || ''));
    if (isNaN(beginn.getTime())) continue;
    const endeRoh = ganztags
      ? new Date(String((ev.end && ev.end.date) || ev.start.date) + 'T00:00:00')
      : new Date(String((ev.end && ev.end.dateTime) || beginn.toISOString()));
    const ende = (endeRoh.getTime() > beginn.getTime()) ? endeRoh : new Date(beginn.getTime() + 60000);

    for (let i = 0; i < 7; i++) {
      const tagDatum = new Date(wochenstart.getFullYear(), wochenstart.getMonth(), wochenstart.getDate() + i);
      const tagEnde = new Date(tagDatum.getFullYear(), tagDatum.getMonth(), tagDatum.getDate() + 1);
      if (!(beginn < tagEnde && ende > tagDatum)) continue;
      const tag = proTag[TAGE[i]];
      tag.termine.push({
        titel: ev.summary || '(ohne Titel)',
        ganztags: ganztags,
        start: ganztags ? null : beginn.toISOString(),
        ende: ganztags ? null : ende.toISOString()
      });
      if (ganztags || ueberlappt(beginn, ende, tagDatum, 11, 30, 13, 30)) tag.mittagBusy = true;
      if (ganztags || ueberlappt(beginn, ende, tagDatum, 18, 0, 20, 30)) tag.abendBusy = true;
    }
  }
}

const busyByDay = {};
for (const t of TAGE) {
  busyByDay[t] = {
    mittag: { busy: proTag[t].mittagBusy, microwaveOnly: proTag[t].mittagBusy },
    abend: { busy: proTag[t].abendBusy },
    termine: proTag[t].termine
  };
}

return [{ json: {
  weekKey: basis.weekKey,
  startDatum: basis.startDatum,
  endDatum: basis.endDatum,
  typ: basis.typ,
  tag: basis.tag,
  slot: basis.slot,
  prefs: basis.prefs,
  freeblocks: basis.freeblocks,
  busyByDay: busyByDay
} }];

// Baut den Kontext fuer die Anthropic-Anfrage.
// recentRecipes = NEGATIVLISTE: Namen aller Rezepte, die in den letzten 28 Tagen
// verwendet wurden (lastUsed) — die KI darf KEINES davon erneut verwenden und
// muss stattdessen komplett neue Rezepte erfinden.
const flags = $('Busy-Flags ableiten').first().json;
// Trainingstage (Kurz-Keys mon..sun) auf deutsche Tages-Keys mappen, damit sie
// direkt zu den von der KI zurueckgegebenen Tagen (montag..sonntag) passen.
const SHORT2DE = { mon: 'montag', tue: 'dienstag', wed: 'mittwoch', thu: 'donnerstag', fri: 'freitag', sat: 'samstag', sun: 'sonntag' };
const prefsRoh = (flags.prefs && typeof flags.prefs === 'object') ? flags.prefs : {};
const prefs = {
  goal: (prefsRoh.goal === 'lose' || prefsRoh.goal === 'gain') ? prefsRoh.goal : 'maintain',
  calorieTrend: (prefsRoh.calorieTrend === 'less' || prefsRoh.calorieTrend === 'more') ? prefsRoh.calorieTrend : 'normal',
  trainingDays: (Array.isArray(prefsRoh.trainingDays) ? prefsRoh.trainingDays : []).map(function (d) { return SHORT2DE[d] || d; })
};

let rezepte = $json;
if (rezepte && typeof rezepte === 'object' && !Array.isArray(rezepte) && Object.keys(rezepte).length === 1 && 'data' in rezepte) rezepte = rezepte.data;
if (!rezepte || typeof rezepte !== 'object' || Array.isArray(rezepte)) rezepte = {};

const grenze = new Date();
grenze.setDate(grenze.getDate() - 28);

const gesehen = new Set();
const recentRecipes = [];
for (const r of Object.values(rezepte)) {
  if (!r || typeof r.name !== 'string' || !r.name.trim()) continue;
  if (!r.lastUsed) continue;
  const benutzt = new Date(String(r.lastUsed));
  if (isNaN(benutzt.getTime()) || benutzt < grenze) continue;
  const name = r.name.trim();
  if (gesehen.has(name.toLowerCase())) continue;
  gesehen.add(name.toLowerCase());
  recentRecipes.push(name);
}
recentRecipes.sort(function (a, b) { return a.localeCompare(b, 'de'); });

return [{ json: {
  weekKey: flags.weekKey,
  startDatum: flags.startDatum,
  typ: flags.typ,
  busyByDay: flags.busyByDay,
  freeblocks: Array.isArray(flags.freeblocks) ? flags.freeblocks : [],
  recentRecipes: recentRecipes,
  tag: flags.tag,
  slot: flags.slot,
  prefs: prefs
} }];

// Wertet die Claude-Antwort aus und baut EIN Multi-Path-Update fuer die RTDB:
// - neue Rezepte  -> nobraine/recipes/<id>                 (Frontend-Schema, deutsch)
// - Wochenplan    -> nobraine/weeks/<wk>/meals/<tag>/<slot> = recipeId
// - Einkaufsliste -> nobraine/weeks/<wk>/shoppinglist/<key> (dedupliziert nach Name+Einheit,
//   Mengen summiert; gleiches Schluesselformat wie das Frontend: auto_<slug(name)>__<slug(einheit)>)
// Freigehaltene Slots (freeblocks) werden nie beschrieben.
const kontext = $('AI-Kontext bauen').first().json;
const resp = $json;
const jetzt = $now.toISO();

const textBlock = (resp && Array.isArray(resp.content) ? resp.content : []).find(function (c) { return c && c.type === 'text' && typeof c.text === 'string'; });
  const antwortText = textBlock ? textBlock.text : null;
if (!antwortText) {
  const fehler = 'Anthropic-API-Fehler: ' + JSON.stringify((resp && (resp.error || resp)) || 'keine Antwort').slice(0, 500);
  return [{ json: { ok: false, weekKey: kontext.weekKey, fehler: fehler } }];
}

let plan = null;
try {
  let t = antwortText.trim();
  const zaun = t.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (zaun) t = zaun[1].trim();
  plan = JSON.parse(t);
} catch (e) {
  return [{ json: { ok: false, weekKey: kontext.weekKey, fehler: 'JSON-Parse-Fehler in der Claude-Antwort: ' + e.message } }];
}
if (!plan || typeof plan !== 'object' || !Array.isArray(plan.days)) {
  return [{ json: { ok: false, weekKey: kontext.weekKey, fehler: 'Claude-Antwort enthielt kein days-Array' } }];
}

const TAGE = ['montag', 'dienstag', 'mittwoch', 'donnerstag', 'freitag', 'samstag', 'sonntag'];
const frei = new Set((kontext.freeblocks || []).map(function (f) { return String(f.tag) + '|' + String(f.slot); }));
// Slot-Modus: NUR den angefragten Tag+Slot neu schreiben, nie die ganze Woche ueberschreiben.
const nurSlot = kontext.typ === 'slot' && typeof kontext.tag === 'string' && typeof kontext.slot === 'string';
const zielTag = nurSlot ? kontext.tag.toLowerCase().trim() : null;
const zielSlot = nurSlot ? kontext.slot.toLowerCase().trim() : null;

function lc(s) { return String(s == null ? '' : s).toLowerCase(); }
function slug(s) { return lc(s).replace(/[^a-z0-9äöü]+/g, '_').replace(/^_+|_+$/g, '') || 'x'; }
function num(v) {
  const s = String(v == null ? '' : v).replace(',', '.').trim();
  if (s.indexOf('/') > -1) { const p = s.split('/'); const a = parseFloat(p[0]); const b = parseFloat(p[1]); if (b) return a / b; }
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
}
function mengeTrennen(amount) {
  const roh = String(amount == null ? '' : amount).trim();
  const m = roh.match(/^([0-9]+(?:[.,][0-9]+)?(?:\s*\/\s*[0-9]+)?)\s*(.*)$/);
  if (!m) return { menge: null, einheit: roh };
  return { menge: num(m[1]), einheit: (m[2] || '').trim() };
}

// Prueft das KI-Schema {name, portions, timeMinutes, ingredients:[{name,amount}], steps:[...]}
// und mappt auf das Frontend-Schema {name, kategorie, portionen, kochzeitMin, zutaten, schritte, tags, lastUsed, ...}
function rezeptPruefen(roh, slotKey) {
  if (!roh || typeof roh !== 'object') return null;
  if (typeof roh.name !== 'string' || !roh.name.trim()) return null;
  if (!Array.isArray(roh.ingredients) || roh.ingredients.length === 0) return null;
  if (!Array.isArray(roh.steps) || roh.steps.length === 0) return null;
  const zutaten = [];
  for (const z of roh.ingredients) {
    if (!z || typeof z.name !== 'string' || !z.name.trim()) continue;
    const mt = mengeTrennen(z.amount);
    zutaten.push({ name: z.name.trim(), menge: mt.menge == null ? '' : mt.menge, einheit: mt.einheit });
  }
  if (zutaten.length === 0) return null;
  const schritte = roh.steps.map(function (s) { return String(s); }).filter(function (s) { return s.trim().length > 0; });
  if (schritte.length === 0) return null;
  return {
    name: roh.name.trim(),
    kategorie: slotKey,
    portionen: Number(roh.portions) > 0 ? Math.round(Number(roh.portions)) : 2,
    kochzeitMin: Number(roh.timeMinutes) > 0 ? Math.round(Number(roh.timeMinutes)) : 30,
    zutaten: zutaten,
    schritte: schritte,
    tags: ['vegetarisch', 'generiert'],
    lastUsed: null,
    erstellt: jetzt,
    aktualisiert: jetzt
  };
}

const updates = {};
const einkauf = {};
let zaehler = 0;
const startTeile = String(kontext.startDatum || '').split('-');
const wochenstart = new Date(Number(startTeile[0]), Number(startTeile[1]) - 1, Number(startTeile[2]));
const idBasis = jetzt.replace(/[^0-9]/g, '').slice(0, 14);

for (const eintrag of plan.days) {
  if (!eintrag || typeof eintrag.day !== 'string') continue;
  const tagKey = eintrag.day.toLowerCase().trim();
  const tagIndex = TAGE.indexOf(tagKey);
  if (tagIndex < 0) continue;
  if (nurSlot && tagKey !== zielTag) continue;
  const datum = new Date(wochenstart.getFullYear(), wochenstart.getMonth(), wochenstart.getDate() + tagIndex);
  const datumIso = datum.getFullYear() + '-' + String(datum.getMonth() + 1).padStart(2, '0') + '-' + String(datum.getDate()).padStart(2, '0');
  const slots = { mittag: eintrag.lunch, abend: eintrag.dinner };
  for (const slotKey of Object.keys(slots)) {
    if (frei.has(tagKey + '|' + slotKey)) continue; // freigehaltene Slots respektieren
    if (nurSlot && slotKey !== zielSlot) continue; // im Slot-Modus nur den angefragten Slot
    const rezept = rezeptPruefen(slots[slotKey], slotKey);
    if (!rezept) continue;
    zaehler += 1;
    const id = 'gen_' + idBasis + '_' + String(zaehler).padStart(2, '0');
    rezept.lastUsed = datumIso;
    updates['nobraine/recipes/' + id] = rezept;
    updates['nobraine/weeks/' + kontext.weekKey + '/meals/' + tagKey + '/' + slotKey] = id;
    for (const z of rezept.zutaten) {
      const key = 'auto_' + slug(z.name) + '__' + slug(z.einheit || '');
      if (!einkauf[key]) einkauf[key] = { name: z.name, einheit: z.einheit || '', menge: 0, unbekannt: false };
      const n = num(z.menge);
      if (n == null) einkauf[key].unbekannt = true; else einkauf[key].menge += n;
    }
  }
}

if (zaehler === 0) {
  return [{ json: { ok: false, weekKey: kontext.weekKey, fehler: 'Claude-Antwort enthielt keine verwertbaren Rezepte' } }];
}

// Im Slot-Modus die Einkaufsliste NICHT neu schreiben - das Frontend aggregiert sie ohnehin
// live aus den Meals, so bleiben die uebrigen Wochentage/Positionen unangetastet.
if (!nurSlot) for (const key of Object.keys(einkauf)) {
  const e = einkauf[key];
  updates['nobraine/weeks/' + kontext.weekKey + '/shoppinglist/' + key] = {
    name: e.name,
    einheit: e.einheit,
    menge: (e.unbekannt && e.menge === 0) ? '' : Math.round(e.menge * 100) / 100,
    checked: false,
    manuell: false
  };
}

return [{ json: { ok: true, weekKey: kontext.weekKey, anzahlRezepte: zaehler, updates: updates } }];
